const original = $('1.2 Offene Belege abrufen').item.json;
// Alle Text-Teile der KI-Antwort lesen: neuere Modelle liefern davor einen (leeren) thinking-Block (Stefan 18.10.2026)
const kiTeile = $input.item.json.content;
const rawText = (Array.isArray(kiTeile) ? kiTeile : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join('\n') || $input.item.json.text || '';

const match = rawText.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('Keine JSON-Antwort in der Claude-Ausgabe gefunden: ' + rawText);
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (e) {
  throw new Error('JSON-Antwort von Claude war fehlerhaft: ' + match[0]);
}

const allowed = ['relevant', 'irrelevant', 'unsicher'];
if (!allowed.includes(parsed.relevance)) {
  throw new Error('Unerwarteter relevance-Wert: ' + parsed.relevance);
}

return {
  json: {
    id: original.id,
    subject: original.subject,
    sender: original.sender,
    source_mailbox: original.source_mailbox,
    relevance_status: parsed.relevance,
    relevance_begruendung: parsed.begruendung || ''
  }
};

// Irrelevanter Beleg: PDF zu den aussortierten Belegen verschieben (SPEICHER 1, Bereich ally)
const daten = $('2.4 Nach Relevanz verzweigen').item.json;
const beleg = $('1.2 Offene Belege abrufen').item.json;
const originalFileName = (beleg.datei_pfad || '').split('/').pop();
if (!originalFileName) throw new Error('Beleg ' + beleg.id + ' hat keinen Ablageort.');
const zielPfad = 'Belegerfassung/Belege-Irrelevant/' + originalFileName;

return {
  json: { ...daten, ziel_pfad_irrelevant: zielPfad, aktion: 'verschieben', bereich: beleg.datei_bereich || 'ally', pfad: beleg.datei_pfad, ziel_bereich: 'ally', ziel_pfad: zielPfad, ueberschreiben: true }
};

const relevanz = $('2.3 Relevanz auswerten').item.json;
// Alle Text-Teile der KI-Antwort lesen: neuere Modelle liefern davor einen (leeren) thinking-Block (Stefan 18.10.2026)
const kiTeile = $input.item.json.content;
const rawText = (Array.isArray(kiTeile) ? kiTeile : []).filter(b => b && b.type === 'text' && b.text).map(b => String(b.text)).join('\n') || $input.item.json.text || '';

const match = rawText.match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('Keine JSON-Antwort in der Claude-Ausgabe gefunden: ' + rawText);
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (e) {
  throw new Error('JSON-Antwort von Claude war fehlerhaft: ' + match[0]);
}

const unsicherheiten = Array.isArray(parsed.unsicherheiten) ? parsed.unsicherheiten.slice() : [];
const mwstFehlt = parsed.mwst_satz === null || parsed.mwst_satz === undefined;
const fehlendePflichtfelder = [
  !parsed.lieferant && 'lieferant',
  !parsed.rechnungsdatum && 'rechnungsdatum',
  !parsed.betrag_brutto && 'betrag_brutto',
  !parsed.kategorie && 'kategorie',
  mwstFehlt && 'mwst_satz'
].filter(Boolean);
const pflichtfelderFehlen = fehlendePflichtfelder.length > 0;

// Steuer für Papierkram bestimmen (Vorgabe Stefan, 14.10.2026): nur aus den Angaben auf der Rechnung.
// Inland: Satz laut Rechnung. EU ohne deutsche USt: EU-Dienstleistung bzw. EU-Warenkauf. Drittland ohne deutsche USt:
// Dienstleistung = Fremdleistung §13b, Ware = Einfuhrumsatzsteuer. Weist die Rechnung deutsche USt aus, wird sie wie im Inland gebucht.
// Papierkram-Kennungen wie in Stefans Papierkram (Fremdleistung §13b mit Leerzeichen am Ende, so von Papierkram geliefert).
const sitz = String(parsed.lieferant_sitz || 'inland').toLowerCase();
const art = String(parsed.ware_oder_dienstleistung || '').toLowerCase();
const datum = String(parsed.rechnungsdatum || '');
const satz = v => { const n = Number(v); return Number.isFinite(n) ? Math.round(n * 100) / 100 : null; };
const mwst = satz(parsed.mwst_satz);
const DE = [0.19, 0.16, 0.07, 0.05, 0];
let satzDe = satz(parsed.steuersatz_de);
// 2. Halbjahr 2020: abgesenkte Sätze
if (datum >= '2020-07-01' && datum <= '2020-12-31') {
  if (satzDe === 0.19) satzDe = 0.16;
  if (satzDe === 0.07) satzDe = 0.05;
}
const pct = s => String(Math.round(s * 100)) + '%';
// Deutsche USt gilt bei einem ausländischen Lieferanten nur als ausgewiesen, wenn sie wirklich auf der Rechnung steht:
// Satz über 0, kein Reverse-Charge-Hinweis und brutto größer als netto. (Vorfall 14.10.2026, Beleg 30: Die KI hatte
// 19 % aus Stefans Klärungsantwort als MwSt-Satz übernommen, obwohl die Rechnung 0 % ausweist.)
const netto = satz(parsed.betrag_netto);
const brutto = satz(parsed.betrag_brutto);
const deUstAusgewiesen = mwst !== null && mwst > 0 && parsed.reverse_charge !== true
  && !(netto !== null && brutto !== null && Math.abs(brutto - netto) < 0.005);
let steuer = null;
let steuerProblem = '';
// Inland mit Steuerschuldnerschaft des Leistungsempfängers (§13b, z. B. Bauleistung): nicht automatisch buchen,
// sondern gleich zur Handarbeit (Stefan 17.10.2026).
const inlandReverseCharge = sitz === 'inland' && parsed.reverse_charge === true;
// Ausländische USt für eine im Ausland verbrauchte Leistung (z. B. Hotel im Ausland): mit 0 % buchen, die
// ausländische Steuer ist nicht als Vorsteuer abziehbar (Stefan 17.10.2026).
const auslUstImAusland = parsed.auslaendische_ust === true && parsed.leistung_im_ausland === true
  && (sitz === 'eu' || sitz === 'drittland');
// Steuerfreie Leistung (z. B. Bank-, Zahlungs-, Versicherungsleistung): steuersatz_de muss ausdrücklich 0 sein,
// ein fehlender oder leerer Wert zählt nicht als 0 (Stefan 17.10.2026).
const satzDeAngegeben = typeof parsed.steuersatz_de === 'number'
  || (typeof parsed.steuersatz_de === 'string' && parsed.steuersatz_de.trim() !== '');
const steuerfrei = satzDeAngegeben && satzDe === 0;
if (inlandReverseCharge) {
  steuerProblem = 'Inländische Rechnung mit Steuerschuldnerschaft des Leistungsempfängers (§13b, z. B. Bauleistung). Bitte von Hand buchen.';
} else if (auslUstImAusland) {
  steuer = { provenance: sitz === 'eu' ? 'eu' : 'foreign', vat_rate: '0%', text: '0% (ausländische USt, nicht abziehbar)' };
} else if (parsed.auslaendische_ust === true) {
  steuerProblem = 'Die Rechnung weist ausländische Umsatzsteuer aus. Dafür gibt es in Papierkram keinen passenden Steuersatz.';
} else if (sitz === 'inland' || deUstAusgewiesen) {
  // Inland oder ausländischer Lieferant mit deutscher Umsatzsteuer auf der Rechnung
  if (mwst === null || !DE.includes(mwst)) steuerProblem = 'MwSt-Satz ' + (parsed.mwst_satz ?? 'fehlt') + ' ist kein deutscher Steuersatz.';
  else steuer = { provenance: 'domestic', vat_rate: mwst, text: pct(mwst) };
} else if (parsed.leistung_im_ausland === true) {
  steuer = { provenance: sitz === 'eu' ? 'eu' : 'foreign', vat_rate: '0%', text: '0% (Leistung im Ausland)' };
} else if (steuerfrei && (sitz === 'eu' || sitz === 'drittland')) {
  // Steuerfreie Leistung aus EU oder Drittland: 0 % statt Klärung (Stefan 17.10.2026)
  steuer = { provenance: sitz === 'eu' ? 'eu' : 'foreign', vat_rate: '0%', text: '0% (steuerfreie Leistung)' };
} else if (!['ware', 'dienstleistung'].includes(art)) {
  steuerProblem = 'Nicht erkennbar, ob Ware oder Dienstleistung - davon hängt der Steuersatz ab.';
} else if (sitz === 'eu') {
  const erlaubt = [0.19, 0.16, 0.07, 0.05];
  if (!erlaubt.includes(satzDe)) steuerProblem = 'Deutscher Steuersatz für diese ' + (art === 'ware' ? 'Ware' : 'Leistung') + ' nicht erkennbar.';
  else { const t = pct(satzDe) + (art === 'ware' ? ' EU-Warenkauf' : ' EU-Dienstleistung'); steuer = { provenance: 'eu', vat_rate: t, text: t }; }
} else if (sitz === 'drittland') {
  if (art === 'dienstleistung') {
    if (![0.19, 0.07].includes(satzDe)) steuerProblem = 'Für Fremdleistungen nach §13b gibt es in Papierkram nur 19 % und 7 %, erkannt wurde ' + (satzDe === null ? 'kein Satz' : pct(satzDe)) + '.';
    else { const t = pct(satzDe) + ' Fremdleistung §13b '; steuer = { provenance: 'foreign', vat_rate: t, text: t.trim() }; }
  } else {
    if (![0.19, 0.16, 0.07, 0.05].includes(satzDe)) steuerProblem = 'Deutscher Steuersatz für diese Ware nicht erkennbar.';
    else { const t = pct(satzDe) + ' Einfuhrumsatzsteuer'; steuer = { provenance: 'foreign', vat_rate: t, text: t }; }
  }
} else {
  steuerProblem = 'Sitz des Lieferanten nicht erkennbar (Inland, EU oder Drittland).';
}
if (steuerProblem) unsicherheiten.push(steuerProblem);

// Nach einer Antwort von Stefan (Hinweis aus BELEG 2) loesen allgemeine Unsicherheiten keine neue Klaerung aus.
// Ist der Beleg dann immer noch nicht buchbar (Pflichtfeld fehlt, Steuer nicht bestimmbar), wird er nicht erneut
// nachgefragt, sondern zur Handarbeit abgelegt (Vorgabe Stefan, 14.10.2026: keine Schleife).
const bereitsGeklaert = !!$('1.2 Offene Belege abrufen').item.json.klaerung_hinweis;
const nichtBuchbar = pflichtfelderFehlen || !steuer;
const unsicher = bereitsGeklaert ? nichtBuchbar : (unsicherheiten.length > 0 || pflichtfelderFehlen);
// Ausländische Umsatzsteuer kann Papierkram nicht abbilden; eine Rückfrage ändert daran nichts, also gleich zur Handarbeit.
// Ausnahme: im Ausland verbrauchte Leistung, oben mit 0 % gebucht. Inland mit §13b ebenso gleich zur Handarbeit (Stefan 17.10.2026).
const auslUst = parsed.auslaendische_ust === true && !auslUstImAusland;
const sofortHandarbeit = auslUst || inlandReverseCharge;
const manuellNoetig = (bereitsGeklaert && nichtBuchbar) || sofortHandarbeit;
const manuellGrund = !manuellNoetig ? ''
  : sofortHandarbeit ? steuerProblem
  : (pflichtfelderFehlen ? 'Auch nach deiner Antwort fehlen Angaben: ' + fehlendePflichtfelder.join(', ') + '.' : 'Auch nach deiner Antwort nicht automatisch buchbar: ' + steuerProblem);

return {
  json: {
    id: relevanz.id,
    subject: relevanz.subject,
    sender: relevanz.sender,
    source_mailbox: relevanz.source_mailbox,
    extrahiert_lieferant: parsed.lieferant || '',
    extrahiert_lieferant_rohtext: parsed.lieferant_rohtext || parsed.lieferant || '',
    extrahiert_leistungsbeschreibung: parsed.leistungsbeschreibung || '',
    extrahiert_rechnungsdatum: parsed.rechnungsdatum || null,
    extrahiert_rechnungsnummer: parsed.rechnungsnummer || '',
    extrahiert_betrag_brutto: parsed.betrag_brutto || null,
    extrahiert_betrag_netto: parsed.betrag_netto || null,
    extrahiert_mwst_satz: parsed.mwst_satz ?? null,
    extrahiert_kategorie: parsed.kategorie || '',
    extrahiert_lieferant_sitz: sitz,
    extrahiert_art: art,
    buchung_provenance: steuer ? steuer.provenance : null,
    buchung_vat_rate: steuer ? steuer.vat_rate : null,
    buchung_steuer_text: steuer ? steuer.text : '',
    extraktion_unsicher: unsicher,
    manuell_noetig: manuellNoetig,
    manuell_grund: manuellGrund,
    bereits_geklaert: bereitsGeklaert,
    unsicherheiten: unsicherheiten,
    fehlende_pflichtfelder: fehlendePflichtfelder,
    extrahiert_klaerungsvorschlag: parsed.klaerungsvorschlag || ''
  }
};

// Duplikat auswerten (Vorgabe Stefan, 14.10.2026): Entscheidend sind die Angaben auf der Rechnung.
// Gleiche Rechnungsnummer beim gleichen Lieferanten = Duplikat: wird nicht gebucht, sondern abgelegt (BELEG 3).
// Ohne Rechnungsnummer, aber gleicher Lieferant, Betrag und Datum +- 3 Tage = Verdacht: einmal nachfragen.
// Hat Stefan einen solchen Verdacht schon beantwortet, wird nicht erneut gefragt.
var daten = $('4.3 Extraktion auswerten').item.json;
var treffer = $input.item.json || {};

function normalize(str) {
  return (str || '').toLowerCase()
    .replace(/gmbh|ag|kg|ug|e\.k\.|inc\.?|ltd\.?|llc|limited|corp\.?|s\.?a\.?r\.?l\.?|b\.?v\.?|&|und/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

var hatTreffer = !!(treffer && treffer.id);
var lieferantPasst = hatTreffer && !!normalize(daten.extrahiert_lieferant) && normalize(treffer.creditor_name_extrahiert) === normalize(daten.extrahiert_lieferant);
var sicher = hatTreffer && !!treffer.exakter_treffer && lieferantPasst;
var frage = hatTreffer && !treffer.exakter_treffer && lieferantPasst && !treffer.duplikat_schon_geklaert;

return {
  json: Object.assign({}, daten, {
    hat_duplikat: sicher,
    duplikat_frage: frage,
    duplikat_art: sicher ? 'exakt' : (frage ? 'wahrscheinlich' : null),
    duplikat_alter_beleg_id: (sicher || frage) ? treffer.id : null,
    duplikat_alter_betrag: (sicher || frage) ? treffer.betrag : null,
    duplikat_altes_rechnungsdatum: (sicher || frage) ? treffer.rechnungsdatum : null,
    duplikat_alter_voucher_id: (sicher || frage) ? treffer.papierkram_voucher_id : null,
    duplikat_alter_status: (sicher || frage) ? treffer.processing_status : null
  })
};

const d = $input.item.json;
let grund;
if (d.duplikat_frage) {
  grund = 'moeglicher_duplikat';
} else if (d.lieferant_match_status) {
  grund = 'lieferant_unklar';
} else if (d.extrahiert_lieferant !== undefined) {
  grund = 'kategorie_unklar';
} else {
  grund = 'relevanz_unklar';
}

return {
  json: {
    ...d,
    klaerung_grund: grund
  }
};

const extraktion = $('4.4a Lieferant normalisieren').item.json;
const suppliers = ($input.item.json.entries || [])
  .filter(c => c.contact_type === 'supplier' && c.record_state === 'active');

function normalize(str) {
  return (str || '').toLowerCase()
    .replace(/gmbh|ag|kg|ug|e\.k\.|&|und/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

function levenshtein(a, b) {
  const m = [];
  for (let i = 0; i <= b.length; i++) m[i] = [i];
  for (let j = 0; j <= a.length; j++) m[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      m[i][j] = b.charAt(i - 1) === a.charAt(j - 1)
        ? m[i - 1][j - 1]
        : Math.min(m[i - 1][j - 1] + 1, m[i][j - 1] + 1, m[i - 1][j] + 1);
    }
  }
  return m[b.length][a.length];
}

const target = normalize(extraktion.extrahiert_lieferant);
const scored = suppliers.map(s => {
  const candidate = normalize(s.name);
  const dist = levenshtein(target, candidate);
  const maxLen = Math.max(target.length, candidate.length, 1);
  const similarity = 1 - dist / maxLen;
  return { id: s.id, name: s.name, similarity };
}).sort((a, b) => b.similarity - a.similarity);

const best = scored[0];
let matchStatus;
if (best && best.similarity >= 0.92) {
  matchStatus = 'eindeutig';
} else if (best && best.similarity >= 0.6) {
  matchStatus = 'mehrdeutig';
} else {
  matchStatus = 'neu';
}

return {
  json: {
    ...extraktion,
    lieferant_match_status: matchStatus,
    lieferant_match_id: matchStatus === 'eindeutig' ? best.id : null,
    lieferant_match_kandidat_name: best ? best.name : null,
    lieferant_match_similarity: best ? Math.round(best.similarity * 100) / 100 : null
  }
};

const match = $('5.2 Lieferant fuzzy matchen').item.json;
const isNew = match.lieferant_match_status === 'neu';

const creditorId = isNew
  ? $input.item.json.id
  : match.lieferant_match_id;

return {
  json: {
    ...match,
    final_creditor_id: creditorId
  }
};

const daten = $('5.6 Lieferant-Ergebnis zusammenführen').item.json;
const mappingTreffer = $input.item.json;

const finaleKategorie = (mappingTreffer && mappingTreffer.kategorie)
  ? mappingTreffer.kategorie
  : daten.extrahiert_kategorie;

return {
  json: {
    ...daten,
    finale_kategorie: finaleKategorie,
    mapping_existiert: !!(mappingTreffer && mappingTreffer.kategorie)
  }
};

