return {
  json: $input.item.json,
  binary: {
    data: $('4.1 PDF für Extraktion laden').item.binary.data
  }
};

const daten = $('6.2 Finale Beleg-Daten zusammenstellen').item.json;

function safe(str) {
  return (str || '').replace(/[\/\\:*?"<>|]/g, '_').trim();
}

const monat = daten.extrahiert_rechnungsdatum.slice(0, 7); // YYYY-MM
const teile = [
  daten.extrahiert_rechnungsdatum,
  safe(daten.extrahiert_lieferant),
  daten.extrahiert_betrag_brutto ? `${daten.extrahiert_betrag_brutto}EUR` : null,
  daten.extrahiert_rechnungsnummer ? safe(daten.extrahiert_rechnungsnummer) : null
].filter(Boolean);

const finalerDateiname = teile.join('_') + '.pdf';
// Ablage in der Buchhaltung über SPEICHER 1 (Server oder eigener Speicherort): PDF aus dem Eingang dorthin verschieben
const finalerPfad = finalerDateiname;
const beleg = $('1.2 Offene Belege abrufen').item.json;

return {
  json: {
    ...daten,
    finaler_dateiname: finalerDateiname,
    finaler_bereich: 'buchhaltung',
    finaler_pfad: finalerPfad,
    aktion: 'verschieben', bereich: beleg.datei_bereich || 'ally', pfad: beleg.datei_pfad || '_',
    ziel_bereich: 'buchhaltung', ziel_pfad: finalerPfad, ueberschreiben: true
  }
};

var daten = $('4.3b Duplikat auswerten').item.json;

function normalize(str) {
  return (str || '').toLowerCase()
    .replace(/gmbh|ag|kg|ug|e\.k\.|&|und/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

return {
  json: Object.assign({}, daten, {
    lieferant_rohtext_normalisiert: normalize(daten.extrahiert_lieferant_rohtext)
  })
};

var daten = $('4.4a Lieferant normalisieren').item.json;
var treffer = $input.item.json;
var hatAlias = !!(treffer && treffer.papierkram_creditor_id);

return {
  json: Object.assign({}, daten, {
    hat_alias: hatAlias,
    alias_creditor_id: hatAlias ? treffer.papierkram_creditor_id : null,
    alias_creditor_name: hatAlias ? treffer.papierkram_creditor_name : null
  })
};

var d = $json;

return {
  json: Object.assign({}, d, {
    lieferant_match_status: 'eindeutig_alias',
    lieferant_match_id: d.alias_creditor_id,
    lieferant_match_kandidat_name: d.alias_creditor_name,
    lieferant_match_similarity: 1,
    final_creditor_id: d.alias_creditor_id
  })
};

const zlib = require('zlib');

if (!$binary || !$binary.data || !$binary.data.data) {
  return {
    json: Object.assign({}, $json, {
      hat_e_rechnung_xml: false,
      e_rechnung_xml_dateiname: null,
      e_rechnung_xml: null
    }),
    binary: $input.item.binary
  };
}

const buffer = Buffer.from($binary.data.data, 'base64');
const text = buffer.toString('latin1');

// Bekannte Standard-Dateinamen fuer ZUGFeRD/Factur-X/XRechnung haben Vorrang,
// als Fallback wird jede eingebettete .xml-Datei akzeptiert.
const bekannteNamen = /factur-x\.xml|zugferd-invoice\.xml|zugferd[\w\-]*\.xml|xrechnung\.xml/i;
const filespecRegex = /\/(?:U?F)\s*\(([^()]*\.xml)\)[\s\S]{0,400}?\/EF\s*<<[\s\S]{0,150}?\/U?F\s+(\d+)\s+0\s+R/gi;

let match;
let bestMatch = null;

while ((match = filespecRegex.exec(text)) !== null) {
  const kandidat = { dateiname: match[1], objNum: match[2] };
  if (bekannteNamen.test(kandidat.dateiname)) {
    bestMatch = kandidat;
    break;
  }
  if (!bestMatch) bestMatch = kandidat;
}

let eRechnungXml = null;
let xmlDateiname = null;

if (bestMatch) {
  xmlDateiname = bestMatch.dateiname;
  const objRegex = new RegExp(bestMatch.objNum + '\\s+0\\s+obj([\\s\\S]*?)endobj');
  const objMatch = text.match(objRegex);

  if (objMatch) {
    const objBody = objMatch[1];
    const objBodyStart = objMatch.index + objMatch[0].indexOf(objBody);
    const streamMatch = objBody.match(/stream\r?\n([\s\S]*?)\r?\nendstream/);

    if (streamMatch) {
      const rawStreamText = streamMatch[1];
      const streamStart = objBodyStart + objBody.indexOf(rawStreamText);
      const streamBuffer = buffer.slice(streamStart, streamStart + rawStreamText.length);
      const isFlate = /\/Filter\s*\/FlateDecode/.test(objBody);

      try {
        eRechnungXml = isFlate
          ? zlib.inflateSync(streamBuffer).toString('utf8')
          : streamBuffer.toString('utf8');
      } catch (e) {
        eRechnungXml = null;
      }
    }
  }
}

return {
  json: Object.assign({}, $json, {
    hat_e_rechnung_xml: !!eRechnungXml,
    e_rechnung_xml_dateiname: xmlDateiname,
    e_rechnung_xml: eRechnungXml
  }),
  binary: $input.item.binary
};

var d = $('7.1 Klärungsgrund setzen').item.json;
// Chat-Layout (Vorgabe Stefan, 11.10.2026): Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Bloecken, keine Listenpunkte, keine Emojis
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : (z.kursiv ? '<em>' + esc(z.t) + '</em>' : esc(z.t)));
const zeileText = z => typeof z === 'string' ? roh(z) : (z.behalten ? String(z.t ?? '') : roh(z.t));
const render = bloecke => {
  const b = bloecke.filter(x => x && (x.titel || (x.zeilen || []).length));
  return {
    html: b.map(x => (x.titel ? '<strong>' + esc(x.titel) + '</strong>' + ((x.zeilen || []).length ? '<br>' : '') : '') + (x.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: b.map(x => (x.titel ? roh(x.titel) + ((x.zeilen || []).length ? '\n' : '') : '') + (x.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
function leer(v) { return v === null || v === undefined || v === ''; }
const w = v => leer(v) ? '-' : String(v);

var grundTexte = {
  relevanz_unklar: 'Unklar, ob dieser Beleg überhaupt buchhaltungsrelevant ist.',
  kategorie_unklar: 'Rechnungsdaten wurden extrahiert, aber mindestens ein Pflichtfeld fehlt oder ist unsicher.',
  lieferant_unklar: 'Der Lieferant konnte nicht eindeutig einem bestehenden Papierkram-Kontakt zugeordnet werden.',
  moeglicher_duplikat: 'Möglicherweise wurde diese Rechnung schon einmal erfasst (z.B. zweimal geschickt).'
};
var grundText = grundTexte[d.klaerung_grund] || '';

const bloecke = [];
bloecke.push({ titel: 'Klärung nötig für einen Beleg.' });
bloecke.push({ titel: 'Grund:', zeilen: [grundText] });
bloecke.push({ titel: 'Beleg:', zeilen: ['Von: ' + w(d.sender), 'Betreff: ' + w(d.subject)] });

if (d.klaerung_grund === 'relevanz_unklar') {
  bloecke.push({ titel: 'Einschätzung der KI:', zeilen: [w(d.relevance_begruendung)] });
  bloecke.push({ titel: 'Bitte antworten mit:', zeilen: ['„relevant“ oder „irrelevant“ (optional mit Kategorie oder Hinweis)'] });
} else {
  bloecke.push({ titel: 'Extrahierte Daten:', zeilen: [
    'Lieferant: ' + w(d.extrahiert_lieferant),
    'Rechnungsdatum: ' + w(d.extrahiert_rechnungsdatum),
    'Rechnungsnummer: ' + w(d.extrahiert_rechnungsnummer),
    'Betrag brutto: ' + w(d.extrahiert_betrag_brutto) + ' EUR',
    'Betrag netto: ' + w(d.extrahiert_betrag_netto) + ' EUR',
    'MwSt-Satz: ' + w(d.extrahiert_mwst_satz),
    'Steuer für Papierkram: ' + w(d.buchung_steuer_text),
    'Kategorie: ' + w(d.extrahiert_kategorie)
  ] });
}

if (d.klaerung_grund === 'kategorie_unklar') {
  if ((d.fehlende_pflichtfelder || []).length) bloecke.push({ titel: 'Fehlende Pflichtfelder:', zeilen: [d.fehlende_pflichtfelder.join(', ')] });
  if ((d.unsicherheiten || []).length) bloecke.push({ titel: 'Unklare Punkte:', zeilen: d.unsicherheiten.map(String) });
  if (d.extrahiert_klaerungsvorschlag) {
    bloecke.push({ titel: 'Vorschlag:', zeilen: [String(d.extrahiert_klaerungsvorschlag)] });
    bloecke.push({ titel: 'Passt der Vorschlag?', zeilen: ['Einfach mit „ja“ antworten oder korrigierte Werte nennen.'] });
  } else {
    bloecke.push({ titel: 'Bitte antworten mit:', zeilen: ['den fehlenden oder korrigierten Werten.'] });
  }
}

if (d.klaerung_grund === 'lieferant_unklar') {
  var aehnlichkeit = leer(d.lieferant_match_similarity) ? '-' : (Math.round(d.lieferant_match_similarity * 100) + '%');
  bloecke.push({ titel: 'Vorgeschlagener Lieferant:', zeilen: [w(d.lieferant_match_kandidat_name) + ' (Ähnlichkeit: ' + aehnlichkeit + ')'] });
  bloecke.push({ titel: 'Bitte antworten:', zeilen: ['„Ja, ist ' + w(d.lieferant_match_kandidat_name) + '“ oder „Nein, ist ein neuer Lieferant“ (plus korrekter Name).'] });
}

if (d.klaerung_grund === 'moeglicher_duplikat') {
  var statusText = { verarbeitet: 'gebucht', klaerung_offen: 'Klärung offen', neu: 'in Bearbeitung', manuell: 'zur Handarbeit', fehler: 'Fehler' };
  bloecke.push({ titel: 'Art des Verdachts:', zeilen: ['Auf der Rechnung ist keine Rechnungsnummer erkennbar. Gleicher Lieferant, gleicher Betrag und Rechnungsdatum höchstens 3 Tage auseinander wie bei einem früher erfassten Beleg.'] });
  bloecke.push({ titel: 'Möglicherweise schon erfasst:', zeilen: [
    'Beleg ' + w(d.duplikat_alter_beleg_id) + ' (' + (statusText[d.duplikat_alter_status] || w(d.duplikat_alter_status)) + ')',
    'Rechnungsdatum (alt): ' + w(d.duplikat_altes_rechnungsdatum),
    'Betrag brutto (alt): ' + w(d.duplikat_alter_betrag) + ' EUR'
  ] });
  bloecke.push({ titel: 'Bitte antworten:', zeilen: ['„ist Duplikat“ (wird abgelegt und nicht gebucht) oder „ist kein Duplikat, bitte buchen“.'] });
}

// Original-PDF geht als eigene Nachricht direkt nach dem Text in den Chat (7.3g); kein Link mehr
bloecke.push({ titel: 'Original-PDF zur Kontrolle:', zeilen: ['kommt direkt nach dieser Nachricht.'] });

var klaerungsfallId = $('7.2 Klärungsfall anlegen').item.json.id;
bloecke.push({ zeilen: ['Referenz: klaerung-' + klaerungsfallId] });

const n = render(bloecke);
return {
  json: Object.assign({}, d, {
    klaerungstext: n.html,
    klaerungstext_plain: n.text,
    klaerungsfall_id: klaerungsfallId
  })
};

